CREATE TABLE IF NOT EXISTS "ai_chat_conversation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "owner_user_type" varchar(16) NOT NULL DEFAULT 'ADMIN',
    "member_id" bigint NULL,
    "chat_mode" varchar(32) NOT NULL DEFAULT 'STANDARD',
    "mcp_client_name" varchar(128) NULL,
    "allow_mutation" bit NOT NULL DEFAULT FALSE,
    "identity_bound_time" datetime NULL,
    "role_id" bigint NULL,
    "title" varchar(256) NOT NULL,
    "model_id" bigint NOT NULL,
    "model" varchar(64) NOT NULL,
    "pinned" bit NOT NULL,
    "pinned_time" datetime NULL,
    "system_message" varchar(1024) NULL,
    "temperature" double NOT NULL,
    "max_tokens" int NOT NULL,
    "max_contexts" int NOT NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
